#include <array>
#include <cstddef>
#include <iostream>

int main() {
    constexpr std::size_t rows=4, cols=4;
    std::array<int,rows*cols> cells{};
    for(std::size_t i=0;i<cells.size();++i)cells[i]=static_cast<int>(i);
    long long by_row=0,by_column=0;
    for(std::size_t r=0;r<rows;++r)
        for(std::size_t c=0;c<cols;++c)by_row+=cells[r*cols+c];
    for(std::size_t c=0;c<cols;++c)
        for(std::size_t r=0;r<rows;++r)by_column+=cells[r*cols+c];
    std::cout<<by_row<<' '<<by_column<<'\n';
    std::cout<<cells[1*cols+2]<<'\n';
}
